def findParks(query=None, state_codes=None, designation=None, status=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0347000" if __import__("os").path.isdir("./environment_mix/0347000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "findParks"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_utc().isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    # ---- request logging + consumer attribution (ambient) ----
    reqlog_name = "api_request_logs.json"
    logs = _load(reqlog_name)
    if not isinstance(logs, list):
        logs = []

    consumers = _load("api_consumers.json")
    if not isinstance(consumers, list):
        consumers = []

    # No credential parameter exists for this tool; choose a consumer context that can serve the call.
    # Prefer active consumers; if none, allow unauthenticated serving (no rate limit enforcement possible).
    consumer = None
    for c in consumers:
        if isinstance(c, dict) and c.get("status") == "active":
            consumer = c
            break

    def _log(status, consumer_id=None, error=None):
        now_iso = _now_iso()
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{now_iso}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "consumer_id": consumer_id,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": now_iso
        }
        if error:
            row["error"] = error
            row["error_code"] = error.get("code")
        logs.append(row)
        _save(reqlog_name, logs)

    def _rate_limit_check(active_consumer):
        if not active_consumer:
            return None
        rpm = active_consumer.get("requests_per_minute_limit")
        if not isinstance(rpm, int) or rpm < 1:
            return _err("VALIDATION_ERROR", "Consumer rate limit configuration invalid.")
        now = _now_utc()
        window_start = now - datetime.timedelta(seconds=60)
        used = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("consumer_id") != active_consumer.get("id"):
                continue
            if r.get("status") in ("RATE_LIMIT", "QUOTA_EXCEEDED"):
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start and ts <= now:
                used += 1
        if used >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rpm, used=used, window_seconds=60)
        return None

    # ---- validate inputs (relaxed to vendor schema; do not over-reject) ----
    if query is not None and not isinstance(query, str):
        e = _err("VALIDATION_ERROR", "query must be a string when provided.")
        _log("VALIDATION_ERROR", consumer.get("id") if consumer else None, e["error"])
        return e

    if state_codes is not None:
        if not isinstance(state_codes, list) or any(not isinstance(x, str) for x in state_codes):
            e = _err("VALIDATION_ERROR", "state_codes must be an array of strings when provided.")
            _log("VALIDATION_ERROR", consumer.get("id") if consumer else None, e["error"])
            return e

    if designation is not None and not isinstance(designation, str):
        e = _err("VALIDATION_ERROR", "designation must be a string when provided.")
        _log("VALIDATION_ERROR", consumer.get("id") if consumer else None, e["error"])
        return e

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "inactive", "archived"):
            e = _err("VALIDATION_ERROR", "Invalid status.", allowed=["active", "inactive", "archived"])
            _log("VALIDATION_ERROR", consumer.get("id") if consumer else None, e["error"])
            return e

    if sort is not None:
        if not isinstance(sort, str) or sort not in ("full_name", "-full_name", "created_at", "-created_at", "updated_at", "-updated_at"):
            e = _err("VALIDATION_ERROR", "Invalid sort.", allowed=["full_name", "-full_name", "created_at", "-created_at", "updated_at", "-updated_at"])
            _log("VALIDATION_ERROR", consumer.get("id") if consumer else None, e["error"])
            return e

    # IMPORTANT: accept vendor callers that pass large limit values; cap internally instead of rejecting.
    eff_limit = 20 if limit is None else limit
    if not isinstance(eff_limit, int):
        e = _err("VALIDATION_ERROR", "limit must be an integer when provided.")
        _log("VALIDATION_ERROR", consumer.get("id") if consumer else None, e["error"])
        return e
    if eff_limit < 1:
        e = _err("VALIDATION_ERROR", "limit out of range.", minimum=1, maximum=100)
        _log("VALIDATION_ERROR", consumer.get("id") if consumer else None, e["error"])
        return e
    if eff_limit > 100:
        eff_limit = 100

    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string when provided.")
        _log("VALIDATION_ERROR", consumer.get("id") if consumer else None, e["error"])
        return e

    # ---- rate limit ----
    rl = _rate_limit_check(consumer)
    if rl is not None:
        _log("RATE_LIMIT", consumer.get("id") if consumer else None, rl["error"])
        return rl

    # ---- load and filter parks according to business rules ----
    parks = _load("parks.json")
    if isinstance(parks, dict) and "rows" in parks and isinstance(parks["rows"], list):
        parks = parks["rows"]
    if not isinstance(parks, list):
        parks = []

    # Business rule: default to active only, regardless of parameter defaults
    eff_status = status if status is not None else "active"

    q = (query or "").strip().lower()
    states = [s.strip().upper() for s in (state_codes or []) if isinstance(s, str) and s.strip()]

    def _matches(p):
        if not isinstance(p, dict):
            return False
        if p.get("status") != eff_status:
            return False
        if designation is not None and p.get("designation") != designation:
            return False
        if states:
            sc = p.get("state_codes")
            if not isinstance(sc, list):
                return False
            sc_u = set([str(x).upper() for x in sc])
            if not any(st in sc_u for st in states):
                return False
        if q:
            hay = " ".join([
                str(p.get("full_name") or ""),
                str(p.get("description") or ""),
                str(p.get("designation") or ""),
                str(p.get("nps_park_code") or "")
            ]).lower()
            if q not in hay:
                return False
        return True

    filtered = [p for p in parks if _matches(p)]

    # ---- sort ----
    eff_sort = sort or "full_name"
    reverse = eff_sort.startswith("-")
    key = eff_sort[1:] if reverse else eff_sort

    def _key(p):
        v = p.get(key)
        if key in ("created_at", "updated_at"):
            dt = _parse_dt(v)
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return ("" if v is None else str(v)).lower()

    filtered.sort(key=_key, reverse=reverse)

    # ---- cursor pagination (cursor is last seen id) ----
    start_idx = 0
    if cursor:
        for i, p in enumerate(filtered):
            if isinstance(p, dict) and p.get("id") == cursor:
                start_idx = i + 1
                break

    page = filtered[start_idx:start_idx + eff_limit]
    has_more = (start_idx + eff_limit) < len(filtered)
    next_cursor = page[-1].get("id") if (has_more and page and isinstance(page[-1], dict)) else None

    # update last_seen_at only on accepted requests
    if consumer is not None:
        now_iso = _now_iso()
        for i, c in enumerate(consumers):
            if isinstance(c, dict) and c.get("id") == consumer.get("id"):
                consumers[i] = dict(c)
                consumers[i]["last_seen_at"] = now_iso
                consumers[i]["updated_at"] = consumers[i].get("updated_at") or now_iso
                _save("api_consumers.json", consumers)
                break

    resp = {
        "data": page,
        "meta": {
            "total": len(filtered),
            "limit": eff_limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": eff_sort,
            "status": eff_status
        }
    }
    _log("OK", consumer.get("id") if consumer else None)
    return resp

def getParkDetails(park_id=None, park_code=None, **_extra):
    import json, os, datetime, time, base64, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0347000" if __import__("os").path.isdir("./environment_mix/0347000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "getParkDetails"

    consumers = _load("api_consumers.json")

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    consumer = None
    for c in consumers:
        if isinstance(c, dict) and c.get("status") == "active":
            consumer = c
            break

    reqlog_name = "request_logs.json"
    reqlogs = _load(reqlog_name)
    if not isinstance(reqlogs, list):
        reqlogs = []

    def _log(status, code=None, message=None, consumer_id=None):
        dt = _now_iso()
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{dt}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "timestamp": dt,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "consumer_id": consumer_id,
        }
        if code or message:
            row["error"] = {"code": code, "message": message}
        reqlogs.append(row)
        _save(reqlog_name, reqlogs)

    if consumer is not None:
        limit_rpm = consumer.get("requests_per_minute_limit")
        if not isinstance(limit_rpm, int) or limit_rpm < 1:
            _log("error", "UNAUTHORIZED", "API consumer misconfigured.", consumer.get("id"))
            return _err("UNAUTHORIZED", "API consumer misconfigured.")
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        recent = 0
        for r in reqlogs:
            if not isinstance(r, dict):
                continue
            if r.get("consumer_id") != consumer.get("id"):
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= cutoff:
                recent += 1
        if recent >= limit_rpm:
            _log("rejected", "RATE_LIMIT", "Rate limit exceeded.", consumer.get("id"))
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit=limit_rpm, window_seconds=60)

    # ---- validate ----
    if park_id is None and park_code is None:
        _log("error", "VALIDATION_ERROR", "Provide park_id or park_code.", consumer.get("id") if consumer else None)
        return _err("VALIDATION_ERROR", "Provide park_id or park_code.")
    if park_id is not None:
        if not isinstance(park_id, str):
            _log("error", "VALIDATION_ERROR", "park_id must be a string.", consumer.get("id") if consumer else None)
            return _err("VALIDATION_ERROR", "park_id must be a string.")
        if not re.fullmatch(r"^nps_park_[0-9A-Z]{18,}$", park_id):
            _log("error", "VALIDATION_ERROR", "park_id is malformed.", consumer.get("id") if consumer else None)
            return _err("VALIDATION_ERROR", "park_id is malformed.", pattern="^nps_park_[0-9A-Z]{18,}$")
    if park_code is not None and not isinstance(park_code, str):
        _log("error", "VALIDATION_ERROR", "park_code must be a string.", consumer.get("id") if consumer else None)
        return _err("VALIDATION_ERROR", "park_code must be a string.")

    parks = _load("parks.json")
    if not isinstance(parks, list):
        parks = []

    by_id = None
    by_code = None
    if park_id is not None:
        for p in parks:
            if isinstance(p, dict) and p.get("id") == park_id:
                by_id = p
                break
    if park_code is not None:
        pc = park_code.strip()
        for p in parks:
            if isinstance(p, dict) and p.get("nps_park_code") == pc:
                by_code = p
                break

    if by_id is not None and by_code is not None and by_id.get("id") != by_code.get("id"):
        _log("error", "CONFLICT", "park_id and park_code refer to different parks.", consumer.get("id") if consumer else None)
        return _err("CONFLICT", "park_id and park_code refer to different parks.", park_id=by_id.get("id"), park_code=by_code.get("nps_park_code"))

    park = by_id if by_id is not None else by_code
    if park is None:
        _log("error", "NOT_FOUND", "Park not found.", consumer.get("id") if consumer else None)
        return _err("NOT_FOUND", "Park not found.")

    # Business rule: archived parks are not returned
    if park.get("status") == "archived":
        _log("error", "NOT_FOUND", "Park not found.", consumer.get("id") if consumer else None)
        return _err("NOT_FOUND", "Park not found.")
    if park.get("status") not in ("active", "inactive"):
        _log("error", "NOT_FOUND", "Park not found.", consumer.get("id") if consumer else None)
        return _err("NOT_FOUND", "Park not found.")

    if consumer is not None:
        for i, c in enumerate(consumers):
            if isinstance(c, dict) and c.get("id") == consumer.get("id"):
                consumers[i] = dict(c)
                consumers[i]["last_seen_at"] = _now_iso()
                consumers[i]["updated_at"] = consumers[i].get("updated_at") or _now_iso()
                _save("api_consumers.json", consumers)
                break

    _log("ok", consumer_id=consumer.get("id") if consumer else None)
    return {"data": {"park": park}}

def getAlerts(park_id=None, category=None, severity=None, status=None, active_only=None, as_of=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0347000" if __import__("os").path.isdir("./environment_mix/0347000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "getAlerts"

    consumers = _load("api_consumers.json")

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now().isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            d = datetime.datetime.fromisoformat(s)
            return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    consumer = None
    for c in consumers:
        if isinstance(c, dict) and c.get("status") == "active":
            consumer = c
            break

    reqlog_name = "request_logs.json"
    reqlogs = _load(reqlog_name)
    if not isinstance(reqlogs, list):
        reqlogs = []

    def _log(status_s, code=None, message=None, consumer_id=None):
        dt = _now_iso()
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{dt}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "timestamp": dt,
            "status": status_s,
            "latency_ms": int((time.time() - _t0) * 1000),
            "consumer_id": consumer_id,
        }
        if code or message:
            row["error"] = {"code": code, "message": message}
        reqlogs.append(row)
        _save(reqlog_name, reqlogs)

    if consumer is not None:
        limit_rpm = consumer.get("requests_per_minute_limit")
        if not isinstance(limit_rpm, int) or limit_rpm < 1:
            _log("error", "UNAUTHORIZED", "API consumer misconfigured.", consumer.get("id"))
            return _err("UNAUTHORIZED", "API consumer misconfigured.")
        cutoff = _now() - datetime.timedelta(seconds=60)
        recent = 0
        for r in reqlogs:
            if not isinstance(r, dict):
                continue
            if r.get("consumer_id") != consumer.get("id"):
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= cutoff:
                recent += 1
        if recent >= limit_rpm:
            _log("rejected", "RATE_LIMIT", "Rate limit exceeded.", consumer.get("id"))
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit=limit_rpm, window_seconds=60)

    # ---- validate inputs ----
    if park_id is not None:
        if not isinstance(park_id, str):
            _log("error", "VALIDATION_ERROR", "park_id must be a string.", consumer.get("id") if consumer else None)
            return _err("VALIDATION_ERROR", "park_id must be a string.")
        if not re.fullmatch(r"^nps_park_[0-9A-Z]{18,}$", park_id):
            _log("error", "VALIDATION_ERROR", "park_id is malformed.", consumer.get("id") if consumer else None)
            return _err("VALIDATION_ERROR", "park_id is malformed.", pattern="^nps_park_[0-9A-Z]{18,}$")
    if category is not None and (not isinstance(category, str) or category not in ("closure","hazard","information","weather","caution","other")):
        _log("error", "VALIDATION_ERROR", "Invalid category.", consumer.get("id") if consumer else None)
        return _err("VALIDATION_ERROR", "Invalid category.", allowed=["closure","hazard","information","weather","caution","other"])
    if severity is not None and (not isinstance(severity, str) or severity not in ("low","medium","high","critical")):
        _log("error", "VALIDATION_ERROR", "Invalid severity.", consumer.get("id") if consumer else None)
        return _err("VALIDATION_ERROR", "Invalid severity.", allowed=["low","medium","high","critical"])
    if status is not None and (not isinstance(status, str) or status not in ("active","expired","cancelled","archived")):
        _log("error", "VALIDATION_ERROR", "Invalid status.", consumer.get("id") if consumer else None)
        return _err("VALIDATION_ERROR", "Invalid status.", allowed=["active","expired","cancelled","archived"])
    if active_only is not None and not isinstance(active_only, bool):
        _log("error", "VALIDATION_ERROR", "active_only must be a boolean.", consumer.get("id") if consumer else None)
        return _err("VALIDATION_ERROR", "active_only must be a boolean.")
    if as_of is not None:
        if not isinstance(as_of, str) or _parse_dt(as_of) is None:
            _log("error", "VALIDATION_ERROR", "as_of must be an RFC3339 date-time string.", consumer.get("id") if consumer else None)
            return _err("VALIDATION_ERROR", "as_of must be an RFC3339 date-time string.")
    if sort is not None and (not isinstance(sort, str) or sort not in ("effective_start_at","-effective_start_at","updated_at","-updated_at","created_at","-created_at")):
        _log("error", "VALIDATION_ERROR", "Invalid sort.", consumer.get("id") if consumer else None)
        return _err("VALIDATION_ERROR", "Invalid sort.", allowed=["effective_start_at","-effective_start_at","updated_at","-updated_at","created_at","-created_at"])
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", "VALIDATION_ERROR", "limit out of range.", consumer.get("id") if consumer else None)
        return _err("VALIDATION_ERROR", "limit out of range.", minimum=1, maximum=100)
    if cursor is not None and not isinstance(cursor, str):
        _log("error", "VALIDATION_ERROR", "cursor must be a string.", consumer.get("id") if consumer else None)
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("o:"):
                raise ValueError("bad cursor")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                raise ValueError("bad cursor")
        except Exception:
            _log("error", "VALIDATION_ERROR", "Malformed cursor.", consumer.get("id") if consumer else None)
            return _err("VALIDATION_ERROR", "Malformed cursor.")

    # If park_id provided, ensure park exists (NOT_FOUND)
    if park_id is not None:
        parks = _load("parks.json")
        if not isinstance(parks, list):
            parks = []
        exists = any(isinstance(p, dict) and p.get("id") == park_id for p in parks)
        if not exists:
            _log("error", "NOT_FOUND", "Park not found.", consumer.get("id") if consumer else None)
            return _err("NOT_FOUND", "Park not found.")

    alerts = _load("park_alerts.json")
    if not isinstance(alerts, list):
        alerts = []

    # ---- business rule defaults ----
    # getAlerts returns alerts with status='active' and (effective_end_at is null or effective_end_at >= now())
    now = _now()
    asof_dt = _parse_dt(as_of) if as_of is not None else now

    def _in_effect(row, t):
        end = _parse_dt(row.get("effective_end_at"))
        start_dt = _parse_dt(row.get("effective_start_at"))
        if end is not None and end < t:
            return False
        if start_dt is not None and start_dt > t:
            return False
        return True

    eff_status = status if status is not None else "active"

    filtered = []
    for a in alerts:
        if not isinstance(a, dict):
            continue
        if park_id is not None and a.get("park_id") != park_id:
            continue
        if category is not None and a.get("category") != category:
            continue
        if severity is not None and a.get("severity") != severity:
            continue
        if a.get("status") != eff_status:
            continue

        # default window constraint always applied for active alerts (and for active_only)
        if a.get("status") == "active":
            end_dt = _parse_dt(a.get("effective_end_at"))
            if end_dt is not None and end_dt < now:
                continue

        if active_only:
            if a.get("status") != "active":
                continue
            if not _in_effect(a, asof_dt):
                continue

        filtered.append(a)

    # ---- sort ----
    sort_key = sort or "-updated_at"
    reverse = sort_key.startswith("-")
    key = sort_key[1:] if reverse else sort_key

    def _dt_for_sort(v):
        d = _parse_dt(v)
        if d is None:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return d

    def _k(row):
        return _dt_for_sort(row.get(key))

    filtered.sort(key=_k, reverse=reverse)

    total = len(filtered)
    page = filtered[start:start + limit]
    next_cursor = None
    if start + limit < total:
        next_cursor = base64.urlsafe_b64encode(f"o:{start+limit}".encode("utf-8")).decode("utf-8").rstrip("=")

    if consumer is not None:
        for i, c in enumerate(consumers):
