        dt = _now_iso()
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{dt}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "timestamp": dt,
            "status": status_s,
            "latency_ms": int((time.time() - _t0) * 1000),
            "consumer_id": consumer_id,
        }
        if code or message:
            row["error"] = {"code": code, "message": message}
        reqlogs.append(row)
        _save(reqlog_name, reqlogs)

