    for c in consumers:
        if isinstance(c, dict) and c.get("status") == "active":
            consumer = c
            break
    if not consumer:
        # no working credential context exists in store
        return _err("UNAUTHORIZED", "No authorized API consumer available to serve this request.")

    # Rate limit enforcement: requests_per_minute_limit, using request log if present, else per-consumer counter file.
    now = _now()
    window_start = now - datetime.timedelta(minutes=1)
    rpm_limit = consumer.get("requests_per_minute_limit")
    if not isinstance(rpm_limit, int) or rpm_limit < 1:
        rpm_limit = 60

    reqlog = _load("api_requests.json")
    using_reqlog = isinstance(reqlog, list) and len(reqlog) >= 0
    if using_reqlog:
        cnt = 0
        for r in reqlog:
