                continue
            if r.get("consumer_id") != consumer.get("id"):
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= window_start and ts <= now and r.get("accepted") is True:
                cnt += 1
        if cnt >= rpm_limit:
            # rejected request; do not update last_seen_at
            latency_ms = int((time.time() - t0) * 1000)
            reqlog.append({
                "id": "req_" + hashlib.sha256(f"{consumer.get('id')}|{time.time()}|getCampgrounds".encode("utf-8")).hexdigest()[:24],
                "consumer_id": consumer.get("id"),
                "endpoint": "getCampgrounds",
                "timestamp": _dt_to_iso(now),
                "accepted": False,
                "status": "RATE_LIMIT",
                "latency_ms": latency_ms
            })
            _save("api_requests.json", reqlog)
            return _err("RATE_LIMIT", "Rate limit exceeded.")
    else:
        rl = _load("rate_limits.json")
        if not isinstance(rl, list):
            rl = []
        rec = None
        for x in rl:
            if isinstance(x, dict) and x.get("consumer_id") == consumer.get("id"):
                rec = x
                break
        if not rec:
            rec = {"consumer_id": consumer.get("id"), "window_start": _dt_to_iso(now), "accepted_count": 0}
            rl.append(rec)
        ws = _parse_dt(rec.get("window_start")) or now
        if ws.tzinfo is None:
            ws = ws.replace(tzinfo=datetime.timezone.utc)
        if now - ws >= datetime.timedelta(minutes=1):
            rec["window_start"] = _dt_to_iso(now)
            rec["accepted_count"] = 0
        if int(rec.get("accepted_count") or 0) >= rpm_limit:
            _save("rate_limits.json", rl)
