            return _err("VALIDATION_ERROR", "min_campsites_count must be a non-negative integer.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit out of range (1-100).")
    allowed_sort = {"name", "-name", "campsites_count", "-campsites_count", "updated_at", "-updated_at", "created_at", "-created_at"}
    if sort is None:
        sort = "name"
    if not isinstance(sort, str) or sort not in allowed_sort:
        return _err("VALIDATION_ERROR", "Invalid sort enum.")

    # Cursor decode
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or len(cursor) > 2048:
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("endpoint") != "getCampgrounds":
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            if obj.get("park_id") != park_id or obj.get("status") != status or obj.get("min_campsites_count") != min_campsites_count or obj.get("sort") != sort or obj.get("limit") != limit:
                return _err("VALIDATION_ERROR", "Cursor does not match request parameters.")
            offset = obj.get("offset")
            if not isinstance(offset, int) or offset < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor offset.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # If park_id specified, ensure it exists (and not archived for scoping? tool says NOT_FOUND if park_id is ... truncated; enforce FK existence)
    parks = _load("parks.json")
    if park_id is not None:
        park_row = None
        for p in parks:
            if isinstance(p, dict) and p.get("id") == park_id:
                park_row = p
                break
        if not park_row:
            return _err("NOT_FOUND", "Park not found.")
        # If park is archived, its children are effectively not addressable through park context
        if park_row.get("status") == "archived":
            return _err("NOT_FOUND", "Park not found.")

    rows = _load("campgrounds.json")
    if not isinstance(rows, list):
        rows = []

    # Filter per business rules: status in ('open','seasonal') unless explicitly requested (status param exists)
    def _valid_amenities_obj(x):
        if x is None:
            return True
        if isinstance(x, dict):
            return True
        # if stored as string, must parse to object
        if isinstance(x, str):
            try:
                y = json.loads(x)
                return isinstance(y, dict)
            except Exception:
                return False
        return False

    filtered = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if park_id is not None and r.get("park_id") != park_id:
            continue

        r_status = r.get("status")
        if status is not None:
            if r_status != status:
                continue
        else:
            if r_status not in ("open", "seasonal"):
                continue

        cc = r.get("campsites_count")
        if min_campsites_count is not None:
            if cc is None:
                continue
            if not isinstance(cc, int):
                continue
            if cc < min_campsites_count:
                continue

        if not _valid_amenities_obj(r.get("amenities_json")):
            # Data integrity: exclude invalid rows rather than erroring reads
            continue

        filtered.append(r)

    # Sorting
    desc = sort.startswith("-")
    key = sort[1:] if desc else sort

    def _keyfunc(x):
        v = x.get(key)
        if key in ("created_at", "updated_at"):
            d = _parse_dt(v)
            if d is None:
                return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            if d.tzinfo is None:
                d = d.replace(tzinfo=datetime.timezone.utc)
            return d
        if key == "campsites_count":
            if isinstance(v, int):
                return v
            return -1
        if key == "name":
            return (v or "").casefold()
        return v

    filtered.sort(key=_keyfunc, reverse=desc)

    total = len(filtered)
    page = filtered[offset:offset + limit]
    next_cursor = None
    if offset + limit < total:
        obj = {
            "v": 1,
            "endpoint": "getCampgrounds",
            "offset": offset + limit,
            "park_id": park_id,
            "status": status,
            "min_campsites_count": min_campsites_count,
            "sort": sort,
            "limit": limit
        }
        next_cursor = base64.urlsafe_b64encode(json.dumps(obj, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    # Accepted request: update last_seen_at and logs/counters
    for c in consumers:
        if isinstance(c, dict) and c.get("id") == consumer.get("id"):
            c["last_seen_at"] = _dt_to_iso(now)
            c["updated_at"] = c.get("updated_at") or _dt_to_iso(now)
            break
    _save("api_consumers.json", consumers)

    latency_ms = int((time.time() - t0) * 1000)
    if using_reqlog:
        reqlog.append({
            "id": "req_" + hashlib.sha256(f"{consumer.get('id')}|{time.time()}|getCampgrounds".encode("utf-8")).hexdigest()[:24],
            "consumer_id": consumer.get("id"),
            "endpoint": "getCampgrounds",
            "timestamp": _dt_to_iso(now),
            "accepted": True,
            "status": "OK",
            "latency_ms": latency_ms
        })
        _save("api_requests.json", reqlog)
    else:
        rec["accepted_count"] = int(rec.get("accepted_count") or 0) + 1
        _save("rate_limits.json", rl)

    return {
        "campgrounds": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": next_cursor is not None
        }
    }

