    if park_id is not None:
        if not isinstance(park_id, str) or not park_pat.match(park_id):
            return _err("VALIDATION_ERROR", "Malformed park_id.")
    allowed_status = {"scheduled", "cancelled", "completed", "archived"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid status enum.")
    da = None
    db = None
    if starts_after is not None:
        if not isinstance(starts_after, str):
            return _err("VALIDATION_ERROR", "starts_after must be an ISO date-time string.")
        da = _parse_dt(starts_after)
        if da is None:
            return _err("VALIDATION_ERROR", "Invalid starts_after date-time.")
        if da.tzinfo is None:
            da = da.replace(tzinfo=datetime.timezone.utc)
    if starts_before is not None:
        if not isinstance(starts_before, str):
            return _err("VALIDATION_ERROR", "starts_before must be an ISO date-time string.")
        db = _parse_dt(starts_before)
        if db is None:
            return _err("VALIDATION_ERROR", "Invalid starts_before date-time.")
        if db.tzinfo is None:
            db = db.replace(tzinfo=datetime.timezone.utc)
    if da is not None and db is not None and da > db:
        return _err("VALIDATION_ERROR", "Invalid time range: starts_after is after starts_before.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit out of range (1-100).")
    allowed_sort = {"start_at", "-start_at", "end_at", "-end_at", "updated_at", "-updated_at", "created_at", "-created_at"}
    if sort is None:
        sort = "start_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        return _err("VALIDATION_ERROR", "Invalid sort enum.")

    # Cursor decode
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or len(cursor) > 2048:
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("endpoint") != "getEvents":
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            if obj.get("park_id") != park_id or obj.get("status") != status or obj.get("starts_after") != starts_after or obj.get("starts_before") != starts_before or obj.get("sort") != sort or obj.get("limit") != limit:
                return _err("VALIDATION_ERROR", "Cursor does not match request parameters.")
            offset = obj.get("offset")
            if not isinstance(offset, int) or offset < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor offset.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # If park_id specified, ensure it exists and not archived
    parks = _load("parks.json")
    if park_id is not None:
        park_row = None
        for p in parks:
            if isinstance(p, dict) and p.get("id") == park_id:
                park_row = p
                break
        if not park_row or park_row.get("status") == "archived":
            return _err("NOT_FOUND", "Park not found.")

    rows = _load("park_events.json")
    if not isinstance(rows, list):
        rows = []

    # Business rules default: status='scheduled' and start_at >= now - 1 day (or null)
    default_floor = now - datetime.timedelta(days=1)
    filtered = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if park_id is not None and r.get("park_id") != park_id:
            continue

        r_status = r.get("status")
        if status is not None:
            if r_status != status:
                continue
        else:
            if r_status != "scheduled":
                continue

        sa = _parse_dt(r.get("start_at"))
        ea = _parse_dt(r.get("end_at"))
        if sa is not None and sa.tzinfo is None:
            sa = sa.replace(tzinfo=datetime.timezone.utc)
        if ea is not None and ea.tzinfo is None:
            ea = ea.replace(tzinfo=datetime.timezone.utc)

        # Enforce end >= start when both present
        if sa is not None and ea is not None and ea < sa:
            continue

        # Default time window rule
        if status is None:  # only apply default scheduled filtering window
            if sa is not None and sa < default_floor:
                continue

        # Explicit filters apply only when start_at present
        if da is not None:
            if sa is None or sa < da:
                continue
        if db is not None:
            if sa is None or sa > db:
                continue

        filtered.append(r)

    # Sorting
    desc = sort.startswith("-")
    key = sort[1:] if desc else sort

    def _keyfunc(x):
        v = x.get(key)
        if key in ("created_at", "updated_at", "start_at", "end_at"):
            d = _parse_dt(v)
            if d is None:
                return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            if d.tzinfo is None:
                d = d.replace(tzinfo=datetime.timezone.utc)
            return d
        return v

    filtered.sort(key=_keyfunc, reverse=desc)

    total = len(filtered)
    page = filtered[offset:offset + limit]
    next_cursor = None
    if offset + limit < total:
        obj = {
            "v": 1,
            "endpoint": "getEvents",
            "offset": offset + limit,
            "park_id": park_id,
            "status": status,
            "starts_after": starts_after,
            "starts_before": starts_before,
            "sort": sort,
            "limit": limit
        }
        next_cursor = base64.urlsafe_b64encode(json.dumps(obj, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    # Accepted request: update last_seen_at and logs/counters
    for c in consumers:
        if isinstance(c, dict) and c.get("id") == consumer.get("id"):
            c["last_seen_at"] = _dt_to_iso(now)
            c["updated_at"] = c.get("updated_at") or _dt_to_iso(now)
            break
    _save("api_consumers.json", consumers)

    latency_ms = int((time.time() - t0) * 1000)
    if using_reqlog:
        reqlog.append({
            "id": "req_" + hashlib.sha256(f"{consumer.get('id')}|{time.time()}|getEvents".encode("utf-8")).hexdigest()[:24],
            "consumer_id": consumer.get("id"),
            "endpoint": "getEvents",
            "timestamp": _dt_to_iso(now),
            "accepted": True,
            "status": "OK",
            "latency_ms": latency_ms
        })
        _save("api_requests.json", reqlog)
    else:
        rec["accepted_count"] = int(rec.get("accepted_count") or 0) + 1
        _save("rate_limits.json", rl)

    return {
        "events": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": next_cursor is not None
        }
    }

def createParkAlert(park_id, title, description, category, severity, effective_start_at=None, effective_end_at=None, source_url=None, status=None, **_extra):
