            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _dt_to_iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            d = _parse_dt(dt)
            return dt if d is None else d.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    # Auth: tool requires auth; no explicit credential parameter, so use ambient active consumer.
    consumers = _load("api_consumers.json")
    consumer = None
    for c in consumers:
        if isinstance(c, dict) and c.get("status") == "active":
            consumer = c
            break
    if not consumer:
        return _err("UNAUTHORIZED", "No authorized API consumer available to serve this request.")

    # Rate limiting
    now = _now()
    window_start = now - datetime.timedelta(minutes=1)
    rpm_limit = consumer.get("requests_per_minute_limit")
    if not isinstance(rpm_limit, int) or rpm_limit < 1:
        rpm_limit = 60

