                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= window_start and ts <= now and r.get("accepted") is True:
                cnt += 1
        if cnt >= rpm_limit:
            latency_ms = int((time.time() - t0) * 1000)
            reqlog.append({
                "id": "req_" + hashlib.sha256(f"{consumer.get('id')}|{time.time()}|createParkAlert".encode("utf-8")).hexdigest()[:24],
                "consumer_id": consumer.get("id"),
                "endpoint": "createParkAlert",
                "timestamp": _dt_to_iso(now),
                "accepted": False,
                "status": "RATE_LIMIT",
                "latency_ms": latency_ms
            })
            _save("api_requests.json", reqlog)
            return _err("RATE_LIMIT", "Rate limit exceeded.")
    else:
        rl = _load("rate_limits.json")
        if not isinstance(rl, list):
            rl = []
        rec = None
        for x in rl:
