        status = "active"
    if not isinstance(status, str) or status not in allowed_status:
        return _err("VALIDATION_ERROR", "Invalid status enum.")

    ds = None
    de = None
    if effective_start_at is not None:
        if not isinstance(effective_start_at, str):
            return _err("VALIDATION_ERROR", "effective_start_at must be an ISO date-time string.")
