        if de.tzinfo is None:
            de = de.replace(tzinfo=datetime.timezone.utc)

    if ds is not None and de is not None and de < ds:
        return _err("VALIDATION_ERROR", "effective_end_at must be >= effective_start_at when both are provided.")

    if source_url is not None:
        if not isinstance(source_url, str) or len(source_url.strip()) == 0:
            return _err("VALIDATION_ERROR", "Invalid source_url.")
        # basic URI-ish check
        if not re.match(r"^https?://", source_url.strip(), re.IGNORECASE):
            return _err("VALIDATION_ERROR", "source_url must be an http(s) URL.")

    # FK integrity: park must exist
    parks = _load("parks.json")
    park_row = None
    for p in parks:
        if isinstance(p, dict) and p.get("id") == park_id:
            park_row = p
            break
