        return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)

    # ---- request logging (observable dynamics) ----
    reqlog_name = "api_request_logs.json"
    logs = _load(reqlog_name)
    if not isinstance(logs, list):
        logs = []

    def _log(status_s, consumer_id=None, error=None):
        now_iso = _now_iso()
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{now_iso}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "consumer_id": consumer_id,
            "status": status_s,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": now_iso,
        }
        if error:
            row["error"] = error
            row["error_code"] = error.get("code")
        logs.append(row)
        _save(reqlog_name, logs)

    # ---- validate inputs ----
    if not isinstance(alert_id, str) or not alert_id:
        err = _err("VALIDATION_ERROR", "alert_id must be a non-empty string.", alert_id=alert_id)
        _log("error", None, err["error"])
        return err

    # Vendor schema pattern: ^nps_alert_[0-9A-Z]{18,}$
    # Datastore uses nps_alt_... ids, and audit shows callers may provide park ids by mistake.
    # Real behavior: accept valid requests consistent with the data; so we resolve by actual park_alerts.id
    # and do not hard-fail on pattern mismatch; only reject if not found.
    if not isinstance(status, str) or status not in {"active", "expired", "cancelled", "archived"}:
        err = _err("VALIDATION_ERROR", "status must be one of: active, expired, cancelled, archived.", status=status)
        _log("error", None, err["error"])
        return err

    # ---- authenticate (ambient) + rate limit ----
    consumers = _load("api_consumers.json")
    if not isinstance(consumers, list):
        consumers = []

    # No explicit credential parameter exists; pick a consumer that can serve this call.
    # Prefer an active consumer under its rate limit. If none are active, but some are suspended/revoked,
    # return UNAUTHORIZED (no usable credential context), not a misleading NOT_FOUND.
    now = _now_utc()
    window_start = now - datetime.timedelta(seconds=60)

    def _consumer_rpm(consumer_id):
        # Count accepted requests in last 60s for this consumer (status == "ok").
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("consumer_id") != consumer_id:
                continue
            if r.get("status") != "ok":
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start and ts <= now:
                cnt += 1
        return cnt

    usable_consumer = None
    any_consumer_rows = False
    for c in consumers:
        if not isinstance(c, dict):
            continue
        any_consumer_rows = True
        if c.get("status") != "active":
            continue
        limit = c.get("requests_per_minute_limit")
        if not isinstance(limit, int) or limit < 1:
            # Skip malformed consumer rows rather than breaking service
            continue
        rpm = _consumer_rpm(c.get("id"))
        if rpm < limit:
            usable_consumer = c
            break

    if usable_consumer is None:
        # If there exists at least one active consumer but all are over limit -> RATE_LIMIT
        any_active = any(isinstance(c, dict) and c.get("status") == "active" for c in consumers)
        if any_active:
            err = _err("RATE_LIMIT", "Rate limit exceeded for all available active API consumers.")
            _log("error", None, err["error"])
            return err
        # Otherwise, no active credentials exist in the store
        err = _err("UNAUTHORIZED", "No active API consumer available to authorize this request.")
        _log("error", None, err["error"])
        return err

    consumer_id = usable_consumer.get("id")

    # ---- load alerts + locate target ----
    alerts = _load("park_alerts.json")
    if not isinstance(alerts, list):
        alerts = []

    # Try to find by exact alert id first (real).
    idx = None
    for i, a in enumerate(alerts):
        if isinstance(a, dict) and a.get("id") == alert_id:
            idx = i
            break

    # If not found and caller passed a park id (as seen in audit), try to resolve to "the" active alert for that park.
    # This is a pragmatic compatibility behavior: only do this when the provided id matches a park id row.
    if idx is None:
        parks = _load("parks.json")
        if not isinstance(parks, list):
            parks = []
        park_exists = any(isinstance(p, dict) and p.get("id") == alert_id for p in parks)
        if park_exists:
            candidates = []
            for i, a in enumerate(alerts):
                if not isinstance(a, dict):
                    continue
                if a.get("park_id") != alert_id:
                    continue
                candidates.append((i, a))
            # Prefer an active alert (then newest updated_at/created_at).
            def _dt_key(row):
                dt = _parse_dt(row.get("updated_at")) or _parse_dt(row.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
                return dt
            active = [(i, a) for (i, a) in candidates if a.get("status") == "active"]
            if active:
                active.sort(key=lambda x: _dt_key(x[1]), reverse=True)
                idx = active[0][0]
            elif candidates:
                candidates.sort(key=lambda x: _dt_key(x[1]), reverse=True)
                idx = candidates[0][0]

    if idx is None:
        err = _err(
            "NOT_FOUND",
            "Alert not found. Provide a valid park_alerts.id (or a park id to target a park's most relevant alert).",
            alert_id=alert_id,
        )
        _log("error", consumer_id, err["error"])
        return err

    alert = alerts[idx]
    if not isinstance(alert, dict):
        err = _err("NOT_FOUND", "Alert not found.", alert_id=alert_id)
        _log("error", consumer_id, err["error"])
        return err

    # ---- lifecycle transition enforcement ----
    transitions = {
        "active": {"expired", "cancelled", "archived"},
        "expired": {"archived"},
        "cancelled": {"archived"},
        "archived": set(),
    }

    current = alert.get("status")
    if current not in transitions:
        err = _err("VALIDATION_ERROR", "Alert has invalid current status in datastore.", current_status=current, alert_id=alert.get("id"))
        _log("error", consumer_id, err["error"])
        return err

    if status == current:
        # Idempotent: still counts as accepted; update consumer last_seen_at but do not mutate alert.
        usable_consumer["last_seen_at"] = _now_iso()
        usable_consumer["updated_at"] = usable_consumer.get("updated_at") or _now_iso()
        for i, c in enumerate(consumers):
            if isinstance(c, dict) and c.get("id") == consumer_id:
                consumers[i] = usable_consumer
                break
        _save("api_consumers.json", consumers)
        _log("ok", consumer_id, None)
        return {"alert": alert}

    if status not in transitions[current]:
        err = _err(
            "INVALID_TRANSITION",
            f"Illegal status transition for park_alerts: {current} → {status}. Allowed: {sorted(list(transitions[current]))}.",
            alert_id=alert.get("id"),
            from_status=current,
            to_status=status,
            allowed=sorted(list(transitions[current])),
        )
        _log("error", consumer_id, err["error"])
        return err

    # ---- business rule: effective_end_at >= effective_start_at if both present ----
    start_dt = _parse_dt(alert.get("effective_start_at"))
    end_dt = _parse_dt(alert.get("effective_end_at"))
    if start_dt is not None and end_dt is not None and end_dt < start_dt:
        err = _err(
            "VALIDATION_ERROR",
            "effective_end_at must be >= effective_start_at when both are present.",
            alert_id=alert.get("id"),
        )
        _log("error", consumer_id, err["error"])
        return err

    # ---- persist mutation ----
    now_iso = _now_iso()
    alert["status"] = status
    alert["updated_at"] = now_iso
    alerts[idx] = alert
    _save("park_alerts.json", alerts)

    # Update consumer last_seen_at only on accepted requests
    usable_consumer["last_seen_at"] = now_iso
    usable_consumer["updated_at"] = usable_consumer.get("updated_at") or now_iso
    for i, c in enumerate(consumers):
        if isinstance(c, dict) and c.get("id") == consumer_id:
            consumers[i] = usable_consumer
            break
    _save("api_consumers.json", consumers)

    _log("ok", consumer_id, None)
    return {"alert": alert}

def getCurrentConsumer(include_quota=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0347000" if __import__("os").path.isdir("./environment_mix/0347000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "getCurrentConsumer"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_utc().isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    reqlog_name = "api_request_logs.json"
    logs = _load(reqlog_name)
    if not isinstance(logs, list):
        logs = []

    consumers = _load("api_consumers.json")
    if not isinstance(consumers, list):
        consumers = []

    def _log(status, consumer_id=None, error=None):
        now_iso = _now_iso()
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{now_iso}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "consumer_id": consumer_id,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": now_iso
        }
        if error:
            row["error"] = error
            row["error_code"] = error.get("code")
        logs.append(row)
        _save(reqlog_name, logs)

    # validate
    if include_quota is not None and not isinstance(include_quota, bool):
        e = _err("VALIDATION_ERROR", "include_quota must be a boolean when provided.")
        _log("VALIDATION_ERROR", None, e["error"])
        return e

    # No explicit credential parameter in this tool. Do not require env API keys.
    # Resolve to a consumer context that can serve the call.
    consumer = None
    for c in consumers:
        if isinstance(c, dict) and c.get("status") == "active":
            consumer = c
            break
    if consumer is None:
        e = _err("UNAUTHORIZED", "No active API consumer available to authorize this request.")
        _log("UNAUTHORIZED", None, e["error"])
        return e

    if consumer.get("status") in ("suspended", "revoked"):
        e = {"error": {"code": "FORBIDDEN", "message": "API consumer is suspended or revoked."}}
        _log("FORBIDDEN", consumer.get("id"), e["error"])
        return e

    # rate limit check (this call counts too)
    rpm = consumer.get("requests_per_minute_limit")
    if not isinstance(rpm, int) or rpm < 1:
        e = _err("VALIDATION_ERROR", "Consumer rate limit configuration invalid.")
        _log("VALIDATION_ERROR", consumer.get("id"), e["error"])
        return e
    now = _now_utc()
    window_start = now - datetime.timedelta(seconds=60)
    used = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("consumer_id") != consumer.get("id"):
            continue
        if r.get("status") in ("RATE_LIMIT", "QUOTA_EXCEEDED"):
            continue
        ts = _parse_dt(r.get("created_at"))
        if ts is None:
            continue
        if ts >= window_start and ts <= now:
            used += 1
    if used >= rpm:
        e = _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rpm, used=used, window_seconds=60)
        _log("RATE_LIMIT", consumer.get("id"), e["error"])
        return e

    # accepted: update last_seen_at
    now_iso = _now_iso()
    for i, c in enumerate(consumers):
        if isinstance(c, dict) and c.get("id") == consumer.get("id"):
            consumers[i] = dict(c)
            consumers[i]["last_seen_at"] = now_iso
            consumers[i]["updated_at"] = consumers[i].get("updated_at") or now_iso
            consumer = consumers[i]
            _save("api_consumers.json", consumers)
            break

    data = dict(consumer)
    if not include_quota:
        data.pop("api_key_hash", None)  # keep opaque internals out; still return status/limits
    else:
        # include rate-limit window stats
        remaining = max(0, rpm - used)
        reset_at = (now + datetime.timedelta(seconds=max(0, int(60 - (now - window_start).total_seconds())))).replace(microsecond=0).isoformat()
        data["quota"] = {
            "limit_per_minute": rpm,
            "used_in_window": used,
            "remaining_in_window": remaining,
            "window_seconds": 60,
            "window_started_at": window_start.replace(microsecond=0).isoformat(),
            "window_resets_at": reset_at
        }
        data.pop("api_key_hash", None)

    _log("OK", consumer.get("id"))
    return {"data": data}
